class HTMLLegendElement extends HTMLElement {
    /**
     * Returns the parent form element.
     *
     * @returns Form.
     */
    get form() {
        let parent = this;
        while (parent) {
            if (parent instanceof HTMLFieldSetElement) {
                return parent.form;
            }
            parent = parent.parentNode;
        }
        return null;
    }
}

